def has_close_elements(numbers, threshold):
    for i in range(len(numbers) - 1):
        for j in range(i + 1, len(numbers)):
            if abs(numbers[i] - numbers[j]) <= threshold:
                return True
    return False

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def add(a, b):
    if type(a) != int or type(b) != int:
        raise TypeError("Invalid input type. Expected integers.")
    return a + b

def max_product(num_str, N, K):
    if N == 1 or K == 0:
        return int(num_str)

    if K == 1:
        return max(int(num_str) * int(num_str[:N-1]), int(num_str[1:]) * int(num_str))

    max_product_str = ""
    for i in range(N-K+1):
        for j in range(K):
            max_product_str += num_str[i]
        product = int(max_product_str) * int(num_str[i+1:i+K+1])
        if product > max_product:
            max_product = product

    return max_product

def largest_prime_factor(n: int) -> int:
    if n == 2:
        return n

    for i in range(2, int(n ** 0.5) + 1):
        while n % i == 0:
            n = n // i
        if n == 1:
            return i

    return n

