def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Sort herbs by value in descending order
    herbs.sort(key=lambda x: x[1], reverse=True)

    # Calculate the maximum total value of herbs that can be picked within the time limit
    total_value = 0
    for herb in herbs:
        time, value = herb
        if T - time >= 0:
            total_value += value
            T -= time
        else:
            break

    return total_value

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    if n == 0:
        return V
    elif n == 1:
        return V - volumes[0]
    else:
        # DP approach to find maximum occupied volume in the box by a subset of items
        dp = [0] * (n + 1)
        dp[0] = 0
        for i in range(1, n + 1):
            for j in range(i):
                dp[i] = max(dp[j] + volumes[i - j], dp[i])
        # Calculate the minimum remaining space in the box
        return V - dp[n]

def calculate_arrangements(n, m, a):
    # Initialize the dp array with the base case
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    # Loop over each flower type
    for i in range(1, n + 1):
        # Loop over each count of pots for the current type
        for j in range(1, m + 1):
            # If the current pot count is greater than the maximum for the current type, use the previous pot count
            if j > a[i - 1]:
                dp[i][j] = dp[i - 1][j]
            # Otherwise, add the previous pot count of the previous type
            else:
                dp[i][j] = (dp[i - 1][j] + dp[i - 2][j - a[i - 1]]) % (10**6 + 7)

    # Return the final solution modulo (10^6 + 7)
    return dp[n][m]
